def transform(grid):
    # Existing rule hypothesis: edge bars emit rays into the field, while each
    # isolated marker emits a line toward the nearest opposing edge.
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    bg=max({v for row in grid for v in row}, key=lambda v:sum(row.count(v) for row in grid))
    # Markers are cells unlike the dominant background and unlike edge bars;
    # each one becomes 4 and emits the ray color 2 toward an edge marker.
    edgevals=set()
    for r in range(h):
        for c in range(w):
            if (r in (0,h-1) or c in (0,w-1)) and grid[r][c]!=bg:
                edgevals.add(grid[r][c])
    marks=[(r,c) for r in range(h) for c in range(w)
           if grid[r][c]!=bg and grid[r][c] not in edgevals]
    for r,c in marks:
        out[r][c]=4
        # connect marker to nearest non-background edge cell on its row
        opts=[]
        for dc in (-1,1):
            x=c+dc
            while 0<=x<w and grid[r][x]==bg: x+=dc
            if 0<=x<w and grid[r][x]!=bg: opts.append((abs(x-c),dc,x))
        if opts:
            _,dc,x=min(opts)
            for q in range(c+dc,x,dc):
                if grid[r][q]==bg: out[r][q]=1
    # Edge marker runs fill the intervening area with the dominant line color
    # except where an unbroken separator row/column interrupts propagation.
    for c in range(w):
        rows=[r for r in range(h) if grid[r][c]!=bg]
        if len(rows)>=2 and rows==list(range(min(rows),max(rows)+1)):
            for r in rows:
                for x in range(c+1,w if c==0 else c):
                    if grid[r][x]==bg: out[r][x]=1
    return out
PY

